import Foundation
import Observation
@MainActor @Observable public final class FeedModel { public private(set)var posts:[FeedPost]=[];public private(set)var next:Cursor?;public private(set)var error:String?;let repository:any FeedRepository;public init(repository:any FeedRepository){self.repository=repository};public func refresh() async {do{let page=try await repository.feed(after:nil);posts=page.0;next=page.1;error=nil}catch{self.error=error.localizedDescription}};public func more()async{guard let next else{return};do{let page=try await repository.feed(after:next);let ids=Set(posts.map(\.id));posts += page.0.filter{!ids.contains($0.id)};self.next=page.1}catch{self.error=error.localizedDescription}};public func toggle(_ post:FeedPost)async{guard let i=posts.firstIndex(where:{$0.id==post.id})else{return};let old=posts[i];posts[i].viewerCheered.toggle();posts[i].cheersCount += posts[i].viewerCheered ? 1:-1;do{try await repository.cheer(post.id,posts[i].viewerCheered,UUID())}catch{posts[i]=old}} }
